/* Search page specific styles */

.results-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(190px, 1fr));
  gap: 20px;
  padding: 16px 24px;
}

.results-grid .card img {
  height: 250px;
}

.results-grid .card-synopsis {
  max-height: 54px;
}

.no-results {
  grid-column: 1 / -1;
  text-align: center;
  color: var(--text-muted);
  padding: 60px 20px;
  font-size: 0.95rem;
}

